import{_ as t,o as a,c as i,a6 as n}from"./chunks/framework.BBdhcoHf.js";const u=JSON.parse('{"title":"SBDP Design","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/sbdp/design.md","filePath":"protocols/sbdp/design.md","lastUpdated":1772055117000}'),r={name:"protocols/sbdp/design.md"};function s(o,e,d,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocols/sbdp/design.md for this page in Markdown format</div><h1 id="sbdp-design" tabindex="-1">SBDP Design <a class="header-anchor" href="#sbdp-design" aria-label="Permalink to “SBDP Design”">​</a></h1><blockquote><p><strong>Authority</strong>: Informational (Non-normative)<br><strong>Purpose</strong>: Design decisions and open questions for the SBDP specification.<br><strong>Status</strong>: Pre-specification — architectural direction is set; wire format and transport bindings are not yet defined.</p></blockquote><p>This document records the design rationale and open questions for the Sideband Direct Protocol (SBDP). It is a prerequisite to writing the normative SBDP specification. See ADR-015 for the key architectural decisions.</p><hr><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to “Goals”">​</a></h2><ul><li>Secure, authenticated SBP sessions without relay infrastructure.</li><li>Same <code>Peer</code> SDK API as relay mode — no user-facing API changes.</li><li>Works on local networks and daemon-to-daemon connectivity; handles NAT traversal via relay- assisted ICE signaling as a fallback path.</li></ul><h2 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to “Non-Goals”">​</a></h2><ul><li>Peer discovery (application responsibility).</li><li>Replacing the relay for scenarios where NAT traversal requires it.</li><li>New framing or RPC semantics — SBP frames are used unchanged.</li></ul><hr><h2 id="relationship-to-sbrp" tabindex="-1">Relationship to SBRP <a class="header-anchor" href="#relationship-to-sbrp" aria-label="Permalink to “Relationship to SBRP”">​</a></h2><p>SBDP and SBRP are both session layers that wrap SBP frames with encryption. They differ in role symmetry and relay dependency:</p><table tabindex="0"><thead><tr><th>Dimension</th><th>SBRP</th><th>SBDP</th></tr></thead><tbody><tr><td>Relay required</td><td>Yes</td><td>No</td></tr><tr><td>Client identity</td><td>Anonymous</td><td>Noise static key (X25519, TOFU pinned)</td></tr><tr><td>Daemon identity</td><td>Ed25519 (pinned via TOFU)</td><td>Noise static key (X25519, TOFU pinned)</td></tr><tr><td>Handshake</td><td>Relay-mediated init/accept</td><td>Direct Noise XX exchange</td></tr><tr><td>NAT traversal</td><td>Relay handles it</td><td>ICE/STUN or relay-assisted fallback</td></tr><tr><td>Pause/resume</td><td>Relay signals pause when daemon disconnects</td><td>N/A — connection is direct</td></tr></tbody></table><p>Both protocols deliver an encrypted <code>SessionChannel</code> to the runtime. The runtime and all higher layers (router, RPC, events) are identical regardless of which session layer is active.</p><hr><h2 id="cryptographic-design" tabindex="-1">Cryptographic Design <a class="header-anchor" href="#cryptographic-design" aria-label="Permalink to “Cryptographic Design”">​</a></h2><h3 id="noise-xx" tabindex="-1">Noise XX <a class="header-anchor" href="#noise-xx" aria-label="Permalink to “Noise XX”">​</a></h3><p>The handshake uses <a href="https://noiseprotocol.org/noise.html#interactive-handshake-patterns-fundamental" target="_blank" rel="noreferrer">Noise XX</a>, which provides:</p><ul><li>Mutual authentication (both parties authenticate their static keys).</li><li>Forward secrecy (ephemeral keys per session).</li><li>Implicit MITM protection in both directions.</li></ul><p>Key material:</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Scope</th></tr></thead><tbody><tr><td>Static keypair</td><td>X25519</td><td>Noise static key (TOFU pinned); required for both peers</td></tr><tr><td>Identity keypair</td><td>Ed25519</td><td>Optional; if present, MUST be bound to Noise static key for cross-transport identity continuity</td></tr><tr><td>Ephemeral keypair</td><td>X25519</td><td>Per-session, discarded after handshake</td></tr><tr><td>Session keys</td><td>ChaCha20-Poly1305</td><td>Per-direction, derived from Noise handshake</td></tr></tbody></table><p>Cipher suite is fixed (no negotiation) — same design principle as SBRP: one suite, zero negotiation overhead.</p><h3 id="tofu-identity-pinning" tabindex="-1">TOFU Identity Pinning <a class="header-anchor" href="#tofu-identity-pinning" aria-label="Permalink to “TOFU Identity Pinning”">​</a></h3><p>Both sides pin each other&#39;s static public key on first connection. Subsequent connections verify against the pinned key. Key mismatch is a fatal error — same behavior as SBRP (see <code>docs/protocols/sbrp/authentication.md</code>). Unlike SBRP, both peers (including daemon/server implementations) MUST persist pinned keys via an <code>identityKeyStore</code>.</p><hr><h2 id="transport-options" tabindex="-1">Transport Options <a class="header-anchor" href="#transport-options" aria-label="Permalink to “Transport Options”">​</a></h2><p>SBDP is transport-agnostic. The session layer wraps whatever <code>TransportConnection</code> is provided:</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Transport</th></tr></thead><tbody><tr><td>Browser ↔ daemon (same network)</td><td>WebRTC DataChannel</td></tr><tr><td>Browser ↔ daemon (NAT)</td><td>WebRTC DataChannel with ICE/STUN</td></tr><tr><td>Daemon ↔ daemon</td><td>QUIC, TCP</td></tr></tbody></table><p>The transport implements <code>TransportConnection</code> from <code>@sideband/transport</code> (see ADR-005).</p><hr><h2 id="nat-traversal" tabindex="-1">NAT Traversal <a class="header-anchor" href="#nat-traversal" aria-label="Permalink to “NAT Traversal”">​</a></h2><p>For browser contexts, WebRTC ICE handles NAT hole-punching. The signaling exchange (SDP and ICE candidates) requires a side channel. Two approaches:</p><p><strong>Option A — Out-of-band signaling (simple):</strong> Application code exchanges ICE candidates via any available channel (HTTP, existing SBRP relay, WebSocket). SDK provides ICE candidate serialization helpers; transport assembly is application responsibility.</p><p><strong>Option B — Relay-assisted ICE (integrated):</strong> The SBRP relay forwards ICE candidate frames between client and daemon during the upgrade negotiation, then the SBDP session takes over. The relay sees only opaque ICE candidate blobs — no keys.</p><p>Option B is preferred for the SDK integration path. It requires an SBRP extension to define upgrade signaling message types and ordering.</p><hr><h2 id="session-lifecycle" tabindex="-1">Session Lifecycle <a class="header-anchor" href="#session-lifecycle" aria-label="Permalink to “Session Lifecycle”">​</a></h2><p>SBDP does not have relay-mediated pause/resume (there is no relay to signal the peer). Instead:</p><ul><li>Connection loss maps directly to <code>reconnecting</code> in the <code>Peer</code> state machine.</li><li>Reconnection uses the same retry policy as SBP sessions.</li><li>TOFU-pinned keys persist across reconnections; each new handshake MUST re-verify against the pinned key.</li></ul><hr><h2 id="open-questions" tabindex="-1">Open Questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to “Open Questions”">​</a></h2><p><em>These must be resolved before writing the normative specification.</em></p><ol><li><p><strong>Noise transcript details</strong>: ADR-015 selected Noise XX, but the spec still needs exact transcript binding rules (capabilities/metadata binding, downgrade resistance markers).</p></li><li><p><strong>Session resumption</strong>: Should SBDP support resuming an interrupted session (continuing sequence counters) or always create fresh sessions? SBRP punts this to the relay.</p></li><li><p><strong>Relay upgrade signal format</strong>: What exact message type and encoding carries ICE candidates over SBRP? Needs coordination with the relay server design.</p></li><li><p><strong>WebRTC fingerprint binding</strong>: WebRTC DTLS requires a certificate, not a raw key. The Noise XX static key and the DTLS certificate are independent unless explicitly bound. Without binding, a transport-layer MITM could observe connection metadata or selectively drop frames even though Noise XX protects payload confidentiality. The spec must define how to bind the DTLS certificate fingerprint to the Noise handshake (e.g., derive from shared entropy or verify against a hash exchanged during Noise XX).</p></li><li><p><strong>Multi-homed connections</strong>: Can a daemon maintain both an SBRP relay connection and an SBDP direct connection simultaneously, with clients choosing? How does the SDK surface this?</p></li><li><p><strong>Relay-assisted discovery</strong>: When a client connects to a daemon via relay, the daemon knows its own local addresses. Should the daemon advertise local discovery hints (LAN IP, mDNS name) through the relay session so the client can attempt a direct upgrade on subsequent connections? Without this, SBDP requires out-of-band address configuration, which makes it effectively opt-in-only for technical users. A <code>ConnectionBundle</code> or similar mechanism could make direct connections transparent.</p></li></ol><hr><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to “Related Documents”">​</a></h2><ul><li><a href="./../../adr/015-p2p-direct-protocol">ADR-015</a>: Key design decisions</li><li><a href="./">SBDP Overview</a>: Stub and relationship to other protocols</li><li><a href="./../sbrp/">SBRP Specification</a>: Reference implementation for session layer pattern</li><li><a href="./../stack">Protocol Stack</a>: Layer boundaries and wrapping rules</li></ul>',46)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
